socket.onmessage = (event) => {
  const updatedTodo = JSON.parse(event.data)

  queryClient.setQueryData(['todos', 'list'], (previous) =>
    previous?.map((todo) =>
      todo.id === updatedTodo.id ? updatedTodo : todo
    ) ?? previous
  )
}

const queryClient = new QueryClient({
  defaultOptions: {
    queries: {
      staleTime: Infinity,
    },
  },
})
